sys_script.script:
(function executeRule(current, previous) {
    // ===== CONFIG (confirmed from your debug) =====
    var HEADER_TABLE = 'x_1797098_pettyc_0_pettycashmain';
    var LINES_TABLE = 'x_1797098_pettyc_0_petty_cash_lines';
    var REF_TO_HEADER = 'pettycashmain_ref'; // line -> header ref
    var LINE_AMOUNT_FIELD = 'total_line_amount'; // amount on line
    var HEADER_TOTAL_FIELD = 'total_line_amount'; // total on header
    var PFX = '[PettyCash SUM while] ';
    // ==============================================

    gs.info(PFX + 'Inside BR ');

    // Validate table/fields once (prevents "Unknown field null")
    var t = new GlideRecord(LINES_TABLE);
    if (!t.isValid() || !t.isValidField(REF_TO_HEADER) || !t.isValidField(LINE_AMOUNT_FIELD)) {
        gs.error(PFX + 'Bad config. table=' + LINES_TABLE + ', ref=' + REF_TO_HEADER + ', amt=' + LINE_AMOUNT_FIELD);
        return;
    }

    gs.info(PFX + 'Updated 1');

    // Collect impacted headers (current + previous if moved/deleted)
    var headers = {};

    function add(h) {
        if (h) headers[h] = true;
    }

    if (current.operation() !== 'delete') add(current.getValue(REF_TO_HEADER));

    var prevHdr = previous ? previous.getValue(REF_TO_HEADER) : '';
    var moved = previous && current.operation() === 'update' &&
        current.getValue(REF_TO_HEADER) !== prevHdr;
    if (current.operation() === 'delete') add(prevHdr);
    if (moved && prevHdr) add(prevHdr);

    gs.info(PFX + 'after delete 2 ');

    function toNum(v) {
        var n = parseFloat(v);
        return isNaN(n) ? 0 : n;
    }

    function r2(n) {
        return Math.round(n * 100) / 100;
    } // optional rounding

    function recalc(headerId) {
        if (!headerId) return;

        // ---- while-loop sum over child lines ----
        var sum = 0;
        var ln = new GlideRecord(LINES_TABLE);
        ln.addQuery(REF_TO_HEADER, headerId);
        ln.query();
        while (ln.next()) {
            sum += toNum(ln.getValue(LINE_AMOUNT_FIELD));
        }
        sum = r2(sum); // keep totals clean (2dp). Remove if you don’t want rounding.

        gs.info(PFX + 'Calculating with header 3 ' + ln + ' total=' + sum);

        // ---- write sum to header ----
        var hdr = new GlideRecord(HEADER_TABLE);
        if (hdr.get(headerId)) {

            var amount = toNum(hdr.getValue('amount')); // header amount <-- NEW
            var balance = r2(amount - sum); // amount_balance = amount - total <-- NEW

            hdr.setWorkflow(false); // avoid loops if header has BRs
            hdr.autoSysFields(false);
            hdr.setValue(HEADER_TOTAL_FIELD, sum);
            hdr.setValue('amount_balance', balance); // <-- NEW
            hdr.update();
            gs.info(PFX + 'Updated 4 ' + hdr.getDisplayValue('number') + ' total=' + sum);
        } else {
            gs.error(PFX + 'Header not found: ' + headerId);
        }
    }

    for (var id in headers)
        if (headers[id]) recalc(id);
})(current, previous);
